<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XPHI_WASM_PLANE=flare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fiber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon</span></span>
